-- TravelQuest: import destinations from "CÁC ĐIỂM DL CỦA NB VÀ QN".
-- Run once in Supabase SQL Editor after confirming the checkpoints table exists.
-- Existing checkpoint rows are preserved; matching names are skipped.
-- Coordinates are approximate map pins; review them before production GPS check-ins.
WITH destinations(name, description, icon, badge, longitude, latitude) AS (
  VALUES
  ('QUẢNG TRƯỜNG BA ĐÌNH – LĂNG CHỦ TỊCH HỒ CHÍ MINH', 'Quảng trường Ba Đình ngày nay gắn với một sự kiện có ý nghĩa đặc biệt trong lịch sử Việt Nam hiện đại: ngày 2/9/1945, Chủ tịch Hồ Chí Minh đọc Tuyên ngôn Độc lập tại đây trước đông đảo nhân dân, tuyên bố sự ra đời của nước Việt Nam Dân chủ Cộng hòa Tư liệu của Bảo tàng Hồ Chí Minh ghi rõ buổi lễ diễn ra lúc 14 giờ tại vườn hoa Ba Đình Điểm thú vị là tên gọi Ba Đình không phải xuất phát từ một sự kiện diễn ra tại đây từ thời phong kiến Tên này được đặt theo Ba Đình – một căn cứ khởi nghĩa chống Pháp ở Thanh Hóa cuối thế kỷ XIX Sau năm 1945, khu vực này tiếp tục trở thành địa điểm tổ chức nhiều sự kiện chính trị quan trọng Lăng Chủ tịch Hồ Chí Minh được xây dựng sau khi Chủ tịch Hồ Chí Minh qua đời năm 1969 và được khánh thành ngày 29/8/1975 Quảng trường có không gian mở rất lớn, được tổ chức theo trục trung tâm hướng về Lăng Điểm thú vị: Ngày 2/9/1945, nơi này khi đó được gọi là Vườn hoa Ba Đình', '📍', 'Khám phá', 105.8348, 21.0368),
  ('HỒ HOÀN KIẾM', 'Hồ Hoàn Kiếm có lịch sử lâu đời và từng mang nhiều tên gọi Hồ có diện tích khoảng 115511 m² Bao quanh hồ là cây xanh, vườn hoa và hệ thống đường phố trung tâm Điểm thú vị: Tháp Rùa không phải là nơi thờ Rùa Vàng Tên gọi này gắn với hình ảnh rùa thường xuất hiện trên gò đất giữa hồ và truyền thuyết trả gươm', '📍', 'Khám phá', 105.8523, 21.0287),
  ('PHỐ CỔ HÀ NỘI', 'Phố cổ Hà Nội hình thành từ khu vực dân cư và thương mại phía Đông Hoàng thành Thăng Long Theo Sở Văn hóa và Thể thao Hà Nội, khu phố cổ có nguồn gốc từ thời Lý – Trần Người dân từ nhiều địa phương tập trung về đây làm nghề, buôn bán, hình thành các phường nghề và cộng đồng cư dân đô thị Sự kết hợp giữa nhà ở – cửa hàng – nghề thủ công – tín ngưỡng tạo nên bản sắc rất riêng của khu phố cổ Điểm thú vị: “Ở phố cổ Hà Nội, tên phố từng có thể nói cho bạn biết người ta bán gì”', '📍', 'Khám phá', 105.8502, 21.0341),
  ('VĂN MIẾU – QUỐC TỬ GIÁM', 'Đây là điểm có lịch sử rất dễ dùng để làm câu hỏi tương tác với khách Các khu vực nối với nhau theo một trục thần đạo, tạo thành một tổng thể kiến trúc có tính trục rất rõ ràng Điểm thú vị: “Văn Miếu được xây năm 1070, còn Quốc Tử Giám được lập năm 1076 – tức là Văn Miếu có trước Quốc Tử Giám 6 năm”', '📍', 'Khám phá', 105.8355, 21.027),
  ('NHÀ THỜ LỚN HÀ NỘI', 'Nhà thờ được xây dựng vào cuối thế kỷ XIX trong quá trình Hà Nội chuyển đổi mạnh về không gian đô thị dưới thời Pháp Nhà thờ mang phong cách Gothic Revival/Tân Gothic Điểm thú vị: Một funfact khá hay “Nhà thờ Lớn có 5 quả chuông nhưng hai tháp chuông chỉ cao khoảng 31 m” Ngoài ra, tên “Nhà thờ Lớn” thực chất là tên gọi dân gian, còn tên chính thức là Nhà thờ Chính tòa Thánh Giuse', '📍', 'Khám phá', 105.8486, 21.0288),
  ('CHÙA TRẤN QUỐC', 'Chùa Trấn Quốc được xem là một trong những ngôi chùa cổ nhất Việt Nam và lâu đời nhất tại Hà Nội Theo các tư liệu lịch sử, tiền thân của chùa là Khai Quốc tự, được dựng vào thời Tiền Lý, gắn với vua Lý Nam Đế khoảng thế kỷ VI Tuy nhiên, một số tài liệu ghi mốc khởi dựng 541–547, trong khi một số nguồn ghi 544–548, vì vậy mốc chính xác có sự khác nhau giữa các tư liệu Chùa nằm trên một bán đảo nhỏ nhô ra phía Đông Hồ Tây, tạo thành một không gian kiến trúc Phật giáo nằm giữa mặt nước Điểm thú vị: Chùa Trấn Quốc đã từng được di chuyển vị trí', '📍', 'Khám phá', 105.8369, 21.0458),
  ('NHÀ HÁT LỚN HÀ NỘI', 'Nhà hát Lớn Hà Nội được chính quyền Pháp khởi công ngày 7/6/1901 và hoàn thành năm 1911 Công trình được xây dựng trong quá trình người Pháp quy hoạch và phát triển khu vực trung tâm Hà Nội Các kiến trúc sư người Pháp Broyer và Harlay tham gia thiết kế; việc thi công chính do Travary và Savelon phụ trách Nhà hát chính thức có buổi biểu diễn đầu tiên vào tháng 12/1911 Sau khi xây dựng, Nhà hát Lớn trở thành một trung tâm quan trọng của đời sống nghệ thuật Hà Nội Đến năm 2011, nhân dịp tròn 100 năm, Nhà hát Lớn và Quảng trường Cách mạng tháng Tám được công nhận là Di tích lịch sử – kiến trúc nghệ thuật cấp quốc gia Công trình từng được trùng tu lớn trong giai đoạn 1995–1997 Nhà hát Lớn được thiết kế theo cảm hứng từ các nhà hát châu Âu, đặc biệt thường được so sánh với Nhà hát Opéra Garnier ở Paris, nhưng được thu nhỏ và điều chỉnh để phù hợp với điều kiện địa phương Điểm thú vị: Trong hơn một thế kỷ tồn tại, công trình này đồng thời trở thành một nhân chứng của quá trình chuyển biến chính trị, xã hội và văn hóa của Hà Nội từ thời thuộc địa sang thời kỳ Việt Nam độc lập', '📍', 'Khám phá', 105.8575, 21.0243),
  ('HOÀNG THÀNH THĂNG LONG', 'Hoàng thành Thăng Long là một trong những di sản lịch sử quan trọng nhất của Hà Nội Là một trong những cổng quan trọng dẫn vào khu vực trung tâm Cấm thành Công trình hiện nay có kiến trúc cổng vòm với hệ thống cửa và tường thành Điểm thú vị: “Có thể đứng trên một vị trí và nhìn thấy lịch sử chồng lên lịch sử”', '📍', 'Khám phá', 105.8411, 21.0358),
  ('ĐÈO MÃ PÍ LÈNG', 'Điểm thú vị: Mã Pí Lèng thường được nhắc đến cùng Con đường Hạnh Phúc, nhưng giá trị đặc biệt của nơi đây không chỉ nằm ở cảnh quan', '📍', 'Khám phá', 105.4006, 23.2036),
  ('CAO NGUYÊN ĐÁ ĐỒNG VĂN', 'Điểm thú vị: Cao nguyên đá Đồng Văn có thể được xem như một “bảo tàng địa chất ngoài trời”', '📍', 'Khám phá', 105.3539, 23.2568),
  ('MỎM ĐÁ TỬ THẦN', 'Điểm thú vị: Tên gọi “Tử Thần” chủ yếu là tên gọi trong du lịch và mạng xã hội', '📍', 'Khám phá', 105.4, 23.28),
  ('SÔNG NHO QUẾ', 'Điểm thú vị: Nho Quế không chỉ là một dòng sông mà còn góp phần tạo nên hẻm vực Tu Sản, một trong những hẻm vực sâu và ấn tượng nhất Đông Nam Á', '📍', 'Khám phá', 105.4, 23.19),
  ('CỘT CỜ LŨNG CÚ', 'Phần chân có 6 phù điêu, thể hiện những hình ảnh gắn với lịch sử và văn hóa Việt Nam Lá cờ có kích thước khoảng 9 × 6 m, tương đương 54 m² Điểm thú vị: Do nằm ở vị trí cao và thường xuyên có gió mạnh, lá cờ trên Cột cờ Lũng Cú phải được thay thường xuyên', '📍', 'Khám phá', 105.315, 23.3607),
  ('NÚI TÂY CÔN LĨNH', 'Điểm thú vị: Tây Côn Lĩnh không phải một ngọn núi đơn lẻ mà là một dãy núi rộng lớn, trong đó đỉnh 2428 m là điểm cao nhất', '📍', 'Khám phá', 104.85, 22.8),
  ('Đỉnh Fansipan', 'Lịch sử: Ngọn núi cao nhất Đông Nam Á (3143m), gắn liền với lịch sử thám hiểm Tây Bắc từ thời Pháp thuộc Kiến trúc: Quần thể tâm linh phong cách chùa cổ Việt Nam thế kỷ 15–16 với các công trình gỗ và đá tự nhiên như Bích Vân Thiền Tự, Đại Tượng Phật A Di Đà bằng đồng', '📍', 'Khám phá', 103.775, 22.3033),
  ('Nhà thờ Đá Sapa', 'Lịch sử: Được người Pháp xây dựng hoàn thành khoảng năm 1935, là dấu tích kiến trúc Pháp cổ toàn vẹn nhất tại Sapa Kiến trúc: Phong cách Gô-tích (Gothic) La Mã, xây bằng đá đẽo liên kết bằng vôi, cát và mật mía', '📍', 'Khám phá', 103.8438, 22.3364),
  ('Bản Cát Cát', 'Lịch sử: Làng nghề thủ công truyền thống của người H''Mông được hình thành từ giữa thế kỷ 19 Kiến trúc: Nhà sàn gỗ truyền thống, cối xay nước bằng gỗ, cầu mây bắc qua suối', '📍', 'Khám phá', 103.827, 22.3236),
  ('Đèo O Quy Hồ', 'Lịch sử: Một trong "Tứ đại đỉnh đèo" vùng Tây Bắc nối liền Lào Cai và Lai Châu Kiến trúc / Cảnh quan: Đường đèo hiểm trở ôm quanh dãy Hoàng Liên Sơn hùng vĩ', '📍', 'Khám phá', 103.766, 22.35),
  ('Y Tý', 'Lịch sử: Vùng đất biên giới lâu đời, nơi sinh sống chính của đồng bào dân tộc Hà Nhì, H''Mông Kiến trúc: Nhà trình tường đặc trưng của người Hà Nhì làm bằng đất nén xốp, mái đắp cỏ tranh giống hình cây nấm', '📍', 'Khám phá', 103.683, 22.633),
  ('Thác Bản Giốc', 'Lịch sử: Thác nước tự nhiên nằm trên đường biên giới Việt - Trung, gắn liền với văn hóa bản địa người Tày Kiến trúc / Cảnh quan: Thác 3 tầng đổ xuống từ độ cao hơn 30m trong vùng địa hình karst thuộc Công viên địa chất UNESCO', '📍', 'Khám phá', 106.7218, 22.8536),
  ('Khu di tích Pác Bó', 'Lịch sử: Nơi Bác Hồ trở về nước ngày 28/01/1941 để trực tiếp lãnh đạo cách mạng Việt Nam Kiến trúc: Cảnh quan tự nhiên kết hợp Đền thờ Chủ tịch Hồ Chí Minh kiến trúc nhà sàn Tày - Nùng', '📍', 'Khám phá', 106.046, 22.995),
  ('Động Ngườm Ngao', 'Lịch sử: Hang động đá vôi thiên nhiên hình thành cách đây khoảng 400 triệu năm Kiến trúc / Cảnh quan: Hệ thống thạch nhũ và măng đá kỳ vĩ do thiên nhiên kiến tạo', '📍', 'Khám phá', 106.69, 22.854),
  ('Hồ Thăng Hen', 'Kiến trúc / Cảnh quan: Hồ nằm giữa các dãy núi đá vôi, mặt nước xanh ngắt quanh năm Fun fact: Dù vào mùa lũ, nước hồ Thăng Hen vẫn giữ nguyên màu xanh ngọc bích chứ không bị đục đỏ như các hồ khác', '📍', 'Khám phá', 106.3, 22.7),
  ('Đèo Mã Phục', 'Lịch sử: Con đèo lịch sử nối liền thành phố Cao Bằng với các huyện biên giới Trùng Khánh, Hạ Lang Kiến trúc / Cảnh quan: Đèo có 7 tầng vòng xoáy ôm lấy 2 khối núi đá vôi tựa như hai con ngựa quỳ', '📍', 'Khám phá', 106.25, 22.7),
  ('VỊNH HẠ LONG', 'Vịnh Hạ Long có lịch sử địa chất lâu đời, bắt đầu từ khoảng 570 triệu năm trước với nhiều môi trường cổ địa lý khác nhau Trong kỷ Ordovician – Silur (500–410 triệu năm trước), khu vực là biển sâu; đến kỷ Carbon – Permi (340–250 triệu năm trước) chuyển thành biển nông, tạo điều kiện hình thành các lớp đá vôi dày Qua hàng trăm triệu năm, đáy biển sụt lún và đá vôi tích tụ, đạt độ dày khoảng 1200 m, tạo nền tảng cho cảnh quan núi đá vôi ngày nay Lịch sử địa chất Vịnh Hạ Long trải qua ba giai đoạn tạo sơn chính: Caledonide vào cuối kỷ Silur (~410 triệu năm trước), Indosinide vào cuối kỷ Trias (~200 triệu năm trước) và Alpide vào cuối kỷ Paleogen (~30 triệu năm trước) Giai đoạn cuối tạo nên sự phân hóa giữa các địa lũy và địa hào, góp phần hình thành địa hình Vịnh Hạ Long', '📍', 'Khám phá', 107.1839, 20.9101),
  ('KHU DI TÍCH YÊN TỬ', 'Yên Tử có lịch sử hơn 700 năm, gắn với sự phát triển của Phật giáo Việt Nam Từ thời nhà Trần, Yên Tử trở thành trung tâm Phật giáo quan trọng khi Trần Nhân Tông lên núi tu hành vào năm 1299 và sáng lập Thiền phái Trúc Lâm Yên Tử Sau đó, các thiền sư Pháp Loa và Huyền Quang tiếp tục phát triển hệ thống chùa, am, tháp Qua nhiều thời kỳ, Yên Tử được bảo tồn, trùng tu và ngày nay trở thành quần thể di tích lịch sử – văn hóa, danh thắng và trung tâm Phật giáo tiêu biểu của Việt Nam Về địa lý, Yên Tử là dãy núi thấp thuộc hệ thống cánh cung Đông Triều, có địa chất và địa hình phức tạp, tạo nên nhiều cảnh quan kỳ vĩ như thác Ngự Dội, thác Vàng, thác Bạc, Cổng Trời, đường Tùng, rừng Trúc và đỉnh Yên Tử Các công trình chùa, am, tháp được xây dựng hài hòa với thiên nhiên', '📍', 'Khám phá', 106.715, 21.158),
  ('ĐẢO CÔ TÔ', 'Cô Tô có tên cổ là Chàng Sơn (Núi Chàng), từ lâu là nơi thuyền bè ngư dân vùng Đông Bắc lui tới nhưng chưa hình thành khu dân cư ổn định do thường xuyên bị cướp biển quấy phá Đầu thời Nguyễn, cư dân từ vùng ven biển Quảng Đông, Phúc Kiến và Hải Nam đến sinh sống Năm 1832, Nguyễn Công Trứ đề nghị triều đình thành lập làng xã và đặt làng đầu tiên là Hướng Hóa, sau đó lập đồn canh phòng giặc biển Thời Pháp thuộc, Cô Tô thuộc châu Hà Cối, phủ Hải Đông, tỉnh Hải Ninh, gồm 5 xã Sau nhiều biến động trong thời kỳ chiến tranh, đến cuối năm 1955, quân Pháp rút khỏi Cô Tô theo Hiệp định Genève', '📍', 'Khám phá', 107.763, 20.978),
  ('BÃI CHÁY', 'Bãi Cháy, tên cổ là Vạ Cháy, thời Pháp được ghi là Vat Chay hoặc Ile aux buissons (đảo bụi rậm) Tên gọi này được cho là bắt nguồn từ việc ngư dân đốt lá phi lao để bảo dưỡng thuyền gỗ, tạo nên khói và lửa quanh năm trên bãi cát ven biển Theo dã sử, Bãi Cháy còn gắn với chiến thắng của quân dân nhà Trần trước đoàn thuyền lương Nguyên – Mông do Trương Văn Hổ chỉ huy Nhiều thuyền bị đốt cháy, lửa theo gió lan vào khu rừng phía tây Cửa Lục, từ đó hình thành tên gọi Bãi Cháy', '📍', 'Khám phá', 107.047, 20.956),
  ('Thành nhà Hồ', '- Lịch sử: Được Hồ Quý Ly (khi đó là Thái sư đại thần triều Trần) cho xây dựng vào mùa xuân năm 1397 (năm Đinh Sửu) dưới tên gọi Thành Tây Đô - Việc dời đô từ Thăng Long về Tây Đô nằm trong chiến lược chuẩn bị kháng chiến chống quân Minh xâm lược và củng cố quyền lực trước khi Hồ Quý Ly truất ngôi nhà Trần, lập ra nhà Hồ năm 1400', '📍', 'Khám phá', 105.604, 20.076),
  ('Khu di tích Lam Kinh', '- Lịch sử: Đây là vùng đất cội nguồn của Dòng họ Lê và là quê hương của anh hùng dân tộc Lê Lợi Nơi đây vào năm 1418 đã diễn ra cuộc Hội thề Lũng Nhai, chính thức phát động cuộc Khởi nghĩa Lam Sơn đánh đuổi quân Minh xâm lược - Sau khi đánh đuổi quân Minh và lên ngôi hoàng đế vào năm 1428 (hiệu Lê Thái Tổ), đặt đô tại Thăng Long (Đông Kinh), vua đã cho xây dựng tại quê nhà một điện thờ lớn gọi là Tây Kinh hay Lam Kinh', '📍', 'Khám phá', 105.435, 19.915),
  ('Khu bảo tồn thiên nhiên Pù Luông', '- Lịch sử: Vùng núi Pù Luông từ lâu đời là địa bàn cư trú lâu đời của đồng bào dân tộc Thái và Mường với nền văn hóa lúa nước truyền thống - Chính thức được chính phủ thành lập làm Khu bảo tồn thiên nhiên vào năm 1999 với diện tích hơn 17600 ha nhằm bảo vệ giá trị đa dạng sinh học của dãy núi vôi Pù Luông - Cúc Phương', '📍', 'Khám phá', 105.16, 20.466),
  ('Bãi biển Sầm Sơn', '- Lịch sử: Bãi biển Sầm Sơn bắt đầu được chính quyền thực dân Pháp phát hiện và đưa vào quy hoạch làm nơi nghỉ mát từ năm 1906 Người Pháp đã cho xây dựng hàng loạt biệt thự, khách sạn sang trọng dành cho quan lại Pháp và triều đình nhà Nguyễn - Trong kháng chiến chống Pháp, Sầm Sơn là điểm đón tiếp hàng vạn cán bộ, chiến sĩ, đồng bào và học sinh miền Nam tập kết ra Bắc theo Hiệp định Giơ-ne-vơ năm 1954', '📍', 'Khám phá', 105.907, 19.742),
  ('Suối Cá Thần Cẩm Lương', '- Lịch sử: Dòng suối Ngọc nằm dưới chân núi Bàn Bổ gắn liền với huyền thoại tâm linh lâu đời của người Mường bản Lương Ngọc - Theo truyền thuyết dân gian, xưa kia có hai vợ chồng nghèo nhặt được một quả trứng lạ, từ trứng nở ra một con rắn Con rắn hiền lành giúp dân làng đánh đuổi thủy quái bảo vệ bản làng nhưng không may bị hy sinh Thương tiếc "Thần Rắn", người dân lập đền thờ và từ đó xuất hiện đàn cá hàng ngàn con luôn túc trực bảo vệ dòng suối', '📍', 'Khám phá', 105.29, 20.23),
  ('Bãi biển Hải Tiến', '- Lịch sử: Vùng biển Hoằng Hóa xưa kia chủ yếu là các làng chài ven biển với nghề đánh bắt hải sản và làm muối lâu đời, gắn liền với di tích lịch sử Đền thờ Thái úy Tô Hiến Thành (xây dựng từ thời nhà Lý) - Dự án phát triển Bãi biển Hải Tiến thành khu du lịch sinh thái biển chính thức được triển khai từ đầu những năm 2010', '📍', 'Khám phá', 105.92, 19.861),
  ('Vườn quốc gia Bến En', '- Lịch sử: Vùng đất Bến En xưa kia là địa bàn sinh sống truyền thống của các dân tộc Mường, Thái với nhiều truyền thuyết thần thoại về lòng sông Mực và các dãy núi đá vôi - Ngày 27/01/1992, Chủ tịch Hội đồng Bộ trưởng (nay là Thủ tướng Chính phủ) đã ký quyết định thành lập Vườn Quốc gia Bến En nhằm bảo vệ hệ sinh thái rừng mưa nhiệt đới sông Mực và bảo tồn nhiều loài động thực vật quý hiếm nằm trong Sách Đỏ', '📍', 'Khám phá', 105.5, 19.62),
  ('Biển Bãi Đông', '- Lịch sử: Bán đảo Nghi Sơn (Tĩnh Gia cũ) có vị trí quân sự - hải phòng chiến lược từ thời phong kiến, từng là nơi đóng quân và xây dựng căn cứ hải quân dưới thời các triều đại Lý, Trần, Lê - Bãi Đông nguyên bản là bãi biển tự nhiên hoang sơ nằm phía sau dãy núi đá vôi Nghi Sơn, ít người qua lại ngoại trừ ngư dân đi biển', '📍', 'Khám phá', 105.95, 19.39),
  ('Thác Mây', '- Lịch sử: Thác Mây nằm trong vùng đệm của Vườn quốc gia Cúc Phương, thuộc địa bàn sinh sống lâu đời của người Mường xã Thạch Lâm - Theo truyền thuyết người Mường truyền miệng qua nhiều thế hệ, 9 tầng thác travertine tự nhiên này được hình thành khi 9 nàng tiên trên trời hạ giới tắm mát và để lại dấu chân khi bay về trời', '📍', 'Khám phá', 105.2, 20.15),
  ('Khu di tích thắng cảnh Hàm Rồng', '- Lịch sử: Làng cổ Đông Sơn nằm trong khu vực Hàm Rồng là nơi phát hiện ra chiếc trống đồng Đông Sơn đầu tiên (năm 1924), khai sinh ra nền Văn hóa Đông Sơn rực rỡ thời kỳ đồ đồng của người Việt cổ - Thời kháng chiến chống Mỹ: Cầu Hàm Rồng bắc qua sông Mã là huyết mạch giao thông quan trọng bậc nhất vận chuyển quân lương vào chiến trường miền Nam', '📍', 'Khám phá', 105.779, 19.807),
  ('Đền Bà Triệu', '- Lịch sử: Đền được xây dựng để phụng thờ Anh hùng dân tộc Triệu Thị Trinh (Bà Triệu), người đã cùng anh trai Triệu Quốc Đạt dấy binh khởi nghĩa chống lại ách đô hộ nhà Ngô vào năm 248 - Sau khi cuộc khởi nghĩa thất bại trên núi Tùng, Bà Triệu tuẫn tiết Để ghi nhớ công ơn "vịt đốm cưỡi voi đánh đuổi quân Ngô", nhân dân địa phương đã lập đền thờ bà dưới chân núi Tùng', '📍', 'Khám phá', 105.74, 19.79),
  ('Động Từ Thức', '- Lịch sử: Động gắn liền với tác phẩm "Từ Thức lấy vợ tiên" trong tập truyện cổ dân gian Truyền kỳ mạn lục của Nguyễn Dữ (thời triều Trần - Hồ) - Theo truyền thuyết, Chàng Từ Thức làm quan tri huyện ở Tống Sơn (Thanh Hóa), vì yêu cảnh đẹp thiên nhiên và chuộc lỗi cho người đẹp giỡn hoa nên đã từ quan về đây đi dạo thưởng cảnh, rồi duyên nợ dẫn lối vào động gặp tiên Giáng Hương', '📍', 'Khám phá', 105.93, 20.02),
  ('Khu di tích Kim Liên', '- Lịch sử: Làng Hoàng Trù (Quê ngoại): Nơi Chủ tịch Hồ Chí Minh cất tiếng khóc chào đời ngày 19/05/1890 và sống những năm tháng thơ ấu (1890–1895) trong tình yêu thương của gia đình ông bà ngoại Hoàng Xuân Đường - Làng Sen (Quê nội): Năm 1901, khi thân sinh Bác là cụ Nguyễn Sinh Sắc đỗ Phó bảng, nhân dân làng Sen đã dựng tặng gia đình cụ ngôi nhà tranh 5 gian Bác Hồ đã sống tại đây trong giai đoạn 1901–1906 trước khi theo cha vào Huế', '📍', 'Khám phá', 105.56, 18.676),
  ('Đền Cuông', '- Lịch sử: Đền được lập nên để phụng thờ An Dương Vương (Thục Пан Vương), vị vua sáng lập ra nước Âu Lạc - Theo sử sách và truyền thuyết dân gian, sau khi để mất thành Cổ Loa do trúng kế Trọng Thủy, An Dương Vương cùng con gái Mỵ Châu chạy về phía Nam Đến chân núi Mộ Dạ sát biển Diễn Châu, đường cùng, vua rẽ sừng rẽ nước xuống biển tự thuẫn', '📍', 'Khám phá', 105.59, 18.8),
  ('Biển Cửa Lò', '- Lịch sử: Tên gọi "Cửa Lò" xuất phát từ tên gọi cổ "Cửa Lĩnh" (cửa sông nơi dãy núi Cửa ra biển) - Từ năm 1907, người Pháp đã khảo sát và phát hiện ra bãi biển Cửa Lò có bờ cát đẹp, độ dốc thoải và nước biển trong xanh, nên đã bắt đầu xây dựng các khu biệt thự dưỡng bệnh dành cho quan chức Pháp', '📍', 'Khám phá', 105.71, 18.805),
  ('Đảo chè Thanh Chương', '- Lịch sử: Huyện Thanh Chương từ hàng chục năm trước đã là vùng quy hoạch cây công nghiệp ngắn và dài ngày của tỉnh Nghệ An, trong đó chè là cây trồng chủ lực - Những năm 2000, dự án xây dựng các đập nước thủy lợi (như đập Cầu Cau) được triển khai để phục vụ tưới tiêu, khiến các ngọn đồi trồng chè biến thành các "ốc đảo" giữa lòng hồ rộng lớn', '📍', 'Khám phá', 105.15, 18.735),
  ('Vườn quốc gia Pù Mát', '- Lịch sử: Vùng rừng Pù Mát là địa bàn sinh sống lịch sử của đồng bào các dân tộc Thái, Thổ, Khơ Mú và đặc biệt là tộc người Đan Lai (tộc người có hủ tục "ngủ ngồi" nổi tiếng do lịch sử trốn chạy chúa Nguyễn) - Ban đầu nơi đây được thành lập làm Khu bảo tồn thiên nhiên Pù Mát vào năm 1995 Đến ngày 08/11/2002, Chính phủ quyết định chuyển hạng thành Vườn Quốc gia Pù Mát', '📍', 'Khám phá', 104.7, 19.05),
  ('Cánh đồng hoa hướng dương', '- Lịch sử: Cánh đồng hoa ban đầu không phải được quy hoạch làm điểm du lịch - Từ năm 2010, Tập đoàn TH (TH True Milk) triển khai dự án trang trại chăn nuôi bò sữa tập trung tại Nghĩa Đàn và trồng hoa hướng dương trên diện tích rộng gần 100 ha để làm nguồn thức ăn giàu dinh dưỡng bổ sung cho đàn bò', '📍', 'Khám phá', 105.3, 19.2),
  ('Khu di tích lịch sử Truông Bồn', '- Lịch sử: Trong kháng chiến chống Mỹ, Truông Bồn (thuộc xã Mỹ Sơn, huyện Đô Lương) là "tọa độ lửa" trọng điểm trên tuyến đường chiến lược 15A – nơi tiếp nhận hàng ngàn tấn lương thực, vũ khí từ miền Bắc chuyển vào miền Nam - Từ năm 1964 đến 1968, không quân Mỹ đã trút xuống Truông Bồn hơn 18900 quả bom các loại', '📍', 'Khám phá', 105.45, 18.85),
  ('Đền Ông Hoàng Mười', '- Lịch sử: Đền được xây dựng từ thời nhà Lê (năm 1634) tại làng Xuân Am, xã Hưng Thịnh - Đền thờ Quan Hoàng Mười – vị thần trong Tín ngưỡng thờ Mẫu Tam phủ của người Việt Theo thần tích dân gian xứ Nghệ, Ông Hoàng Mười là giáng sinh của Tướng quân Nguyễn Xí (thời Lê Sơ) hoặc Tướng quân Lê Khôi (cháu Lê Lợi), những vị tướng có công lớn đánh đuổi giặc ngoại xâm và mở mang đất nước', '📍', 'Khám phá', 105.73, 18.69),
  ('Đỉnh Pu Xai Lai Leng', '- Lịch sử: Dãy núi Pu Xai Lai Leng có vị trí địa - chính trị quan trọng, nằm trên đường biên giới tự nhiên giữa Việt Nam và Lào - Đây là địa bàn cư trú lâu đời của đồng bào dân tộc H''Mông, Khơ Mú với lối sống gắn liền với rừng già và văn hóa nương rẫy', '📍', 'Khám phá', 104.15, 19.35),
  ('Trại Cừu Yên Thành', '- Lịch sử: Trại cừu xóm 11 (xã Bảo Thành, huyện Yên Thành) bắt đầu hình thành từ khoảng năm 2015 - Ban đầu, một hộ dân tại địa phương đã mạnh dạn đầu tư mua hàng trăm con cừu giống từ Ninh Thuận về nuôi thử nghiệm trên diện tích đồng cỏ đồi dốc Yên Thành để phát triển kinh tế trang trại lấy thịt và lông', '📍', 'Khám phá', 105.35, 18.98),
  ('Núi Langbiang', 'Lịch sử: Tên gọi bắt nguồn từ thiên tình sử cảm động của chàng K''lang và nàng H''biang thuộc bộ tộc K''Ho sinh sống lâu đời trên cao nguyên Kiến trúc: Cảnh quan thiên nhiên núi rừng cao nguyên hùng vĩ Trên đỉnh Ra-đà (cao 1925m) có đặt bức tượng đúc hình hai nhân vật K''lang và H''biang', '📍', 'Khám phá', 108.436, 12.039),
  ('Thiền Viện Trúc Lâm & Hồ Tuyền Lâm', 'Lịch sử: Xây dựng từ năm 1993 đến năm 1994, do Thiền sư Thích Thanh Từ sáng lập, là một trong những trung tâm lớn nhất của dòng thiền Trúc Lâm Yên Tử Kiến trúc: Mang nét kiến trúc Phật giáo truyền thống Việt Nam, nằm ẩn mình giữa rừng thông bạt ngàn hướng thẳng mặt ra Hồ Tuyền Lâm', '📍', 'Khám phá', 108.442, 11.905),
  ('Dinh III Bảo Đại', 'Lịch sử: Xây dựng từ năm 1933 đến năm 1938, nơi đây từng là nơi làm việc và sinh sống của vị vua cuối cùng triều Nguyễn – Vua Bảo Đại cùng gia đình Kiến trúc: Thiết kế mang phong cách tân cổ điển Châu Âu do kiến trúc sư Paul Veysseyre và Huỳnh Tấn Phát thực hiện, nằm trọn giữa đồi thông', '📍', 'Khám phá', 108.435, 11.932),
  ('Thác Datanla', 'Lịch sử: Gắn liền với các truyền thuyết đại ngàn của người K''Ho về dũng sĩ K''lang đánh bầy thú dữ bảo vệ buôn làng Kiến trúc: Cảnh quan thác nước tự nhiên đổ qua nhiều thềm đá tung bọt trắng xóa giữa thung lũng rừng nguyên sinh xanh mát', '📍', 'Khám phá', 108.454, 11.899),
  ('Trại giam Tù binh Phú Quốc', 'Lịch sử: Thực dân Pháp xây dựng năm 1946, sau đó Mỹ - Ngụy mở rộng năm 1967 thành trại giam tù binh lớn nhất miền Nam Việt Nam (giam >40000 chiến sĩ) Nơi đây đã được công nhận là Di tích quốc gia đặc biệt Kiến trúc: Dạng trại dã chiến rộng 400ha Mái và tường quây hoàn toàn bằng tôn sóng oi nóng, bao quanh bởi vô số lớp rào kẽm gai và chòi canh gác có đèn chiếu sáng', '📍', 'Khám phá', 104.014, 10.046),
  ('Quần đảo Nam Du', 'Lịch sử: Quần đảo hoang sơ gồm 21 hòn đảo lớn nhỏ nằm trong vịnh Thái Lan Kiến trúc: Cảnh quan biển đảo hoang sơ với những bãi cát trắng hàng dừa nghiêng bóng, bãi đá cuội và các làng chài ven biển', '📍', 'Khám phá', 104.37, 9.685),
  ('Chùa Hang - Hòn Phụ Tử', 'Lịch sử: Chùa Hang (Hải Sơn Tự) được các vị sư dựng từ đầu thế kỷ 18 Hòn Phụ Tử gắn liền với truyền thuyết tình cha con hy sinh diệt quái vật biển bảo vệ dân làng Kiến trúc: Chùa nằm trọn trong hang đá vôi thiên nhiên sâu trong lòng núi, lòng hang có nhiều thạch nhũ kỳ ảo mở ra mép biển', '📍', 'Khám phá', 104.59, 10.19),
  ('Đền thờ Cụ Nguyễn Trung Trực', 'Lịch sử: Đền thờ vị anh hùng dân tộc Nguyễn Trung Trực – người lãnh đạo nghĩa quân chống Pháp với 2 chiến công lừng lẫy (đốt cháy tàu Espérance và chiếm đồn Rạch Giá) Kiến trúc: Xây dựng theo phong cách kiến trúc đình đền truyền thống Nam Bộ, mái lợp ngói âm dương, các góc đao cong vút chạm khắc hình rồng', '📍', 'Khám phá', 104.49, 10.38),
  ('Grand World Phú Quốc', 'Lịch sử: Là tổ hợp nghỉ dưỡng – giải trí siêu hiện đại do Vingroup đầu tư xây dựng và đưa vào vận hành từ năm 2021 tại Bắc đảo Phú Quốc Kiến trúc: Thiết kế mang phong cách kiến trúc Châu Âu cổ điển, điểm nhấn là dòng sông Venice thu nhỏ với các dãy nhà phố rực rỡ sắc màu', '📍', 'Khám phá', 103.856, 10.327),
  ('Bưu điện Trung tâm Sài Gòn', 'Lịch sử: Công trình được chính quyền thực dân Pháp khởi công xây dựng vào năm 1886 và chính thức hoàn thành, đưa vào hoạt động năm 1891 Sự ra đời của Bưu điện nằm trong quy hoạch đô thị hóa Sài Gòn nhằm thiết lập hệ thống thông tin liên lạc hiện đại kết nối Nam Kỳ với chính quốc Pháp và toàn thế giới Qua hơn một thế kỷ tồn tại, nơi đây không chỉ chứng kiến nhiều biến cố lịch sử quan trọng của thành phố trong hai cuộc chiến tranh chống Pháp và chống Mỹ mà còn giữ vững vai trò là trung tâm bưu chính cốt lõi và biểu tượng văn hóa lâu đời của TPHCM Kiến trúc: Do kiến trúc sư Gustave Eiffel phối hợp cùng Auguste Vildieu thiết kế Phong cách kết hợp giữa kiến trúc Châu Âu cổ điển và đường nét trang trí phương Đông, nổi bật với hệ thống vòm mái rộng và hoa văn sắt tinh xảo', '📍', 'Khám phá', 106.699, 10.7798),
  ('Nhà thờ Đức Bà', 'Lịch sử: Được khởi công xây dựng vào ngày 7/10/1877 và khánh thành ngày 11/4/1880 do Linh mục Colombert đặt đá xây dựng, nhằm phục vụ nhu cầu làm lễ cho quân đội Pháp và cộng đồng Công giáo tại Sài Gòn lúc bấy giờ Toàn bộ kinh phí do ngân sách Nam Kỳ chi trả (khoảng 2,5 triệu franc Pháp) Năm 1959, Tòa thánh Vatican đã nâng cấp nhà thờ lên hàng Tiểu Vương cung Thánh đường (Basilica) Công trình là chứng nhân cho sự du nhập và phát triển của Công giáo tại miền Nam cũng như các bước chuyển mình của lịch sử đô thị Sài Gòn Kiến trúc: Mang phong cách Roman kết hợp Gothic cổ điển, nổi bật với hai tháp chuông cao hơn 57m và lớp gạch nung Marseille màu đỏ giữ nguyên màu sắc tươi mới qua hơn một thế kỷ', '📍', 'Khám phá', 106.6994, 10.7798),
  ('Dinh Độc Lập', 'Lịch sử: Công trình ban đầu là Dinh Norodom được người Pháp xây dựng từ năm 1868 đến 1871 làm nơi ở cho Thống đốc Nam Kỳ Năm 1954, Dinh được bàn giao cho chính quyền Việt Nam Cộng hòa và đổi tên thành Dinh Độc Lập Sau khi bị hư hại nặng do ném bom năm 1962, Tổng thống Ngô Đình Diệm cho san bằng và xây lại công trình mới từ năm 1962 đến 1966 Nơi đây từng là đại bản doanh quyền lực của các đời Tổng thống VNCH Trưa ngày 30/4/1975, xe tăng của quân Giải phóng húc văng cổng chính, đánh dấu mốc lịch sử kết thúc chiến tranh, thống nhất đất nước Công trình đã được xếp hạng Di tích quốc gia đặc biệt năm 2009 Kiến trúc: Do KTS Ngô Viết Thụ thiết kế, mang phong cách kiến trúc hiện đại kết hợp triết lý phong thủy và triết lý phương Đông (mặt bằng tạo hình thành chữ "CÁT" mang ý nghĩa may mắn)', '📍', 'Khám phá', 106.6953, 10.777),
  ('Chợ Bến Thành', 'Lịch sử: Tiền thân là một ngôi chợ bằng gỗ lá nằm bên bờ sông Bến Nghé (gần bến đò vào thành Gia Định) xuất hiện từ đầu thế kỷ 19 Khi người Pháp chiếm Sài Gòn, chợ bị cháy và được xây lại Đến năm 1912, do chợ cũ xuống cấp, chính quyền Pháp cùng hãng thầu Brossard et Maupin khởi công xây dựng chợ mới tại khu vực đầm lầy Bồ Tát được san lấp (vị trí hiện nay) và chính thức khánh thành năm 1914 Chợ Bến Thành đã chứng kiến sự phát triển thương mại sôi động của Gia Định - Sài Gòn qua nhiều thời kỳ và trở thành biểu tượng giao thương lâu đời nhất của thành phố Kiến trúc: Thiết kế hình chữ nhật với 4 cổng chính hướng ra 4 mặt đường lớn (Đông, Tây, Nam, Bắc) và điểm nhấn là tháp đồng hồ 3 mặt ở cổng Nam', '📍', 'Khám phá', 106.698, 10.7725),
  ('Bảo tàng Chứng tích Chiến tranh', 'Lịch sử: Được thành lập vào ngày 4/9/1975 với tên gọi ban đầu là "Nhà trưng bày tội ác Mỹ - Ngụy" Sau đó, công trình đổi tên thành "Nhà trưng bày tội ác chiến tranh xâm lược" năm 1990 và đổi thành "Bảo tàng Chứng tích Chiến tranh" từ năm 1995 trong bối cảnh Việt Nam bình thường hóa quan hệ ngoại giao với Hoa Kỳ Bảo tàng ra đời nhằm lưu trữ, nghiên cứu và trưng bày các tư liệu, hiện vật về hậu quả tàn khốc của các cuộc chiến tranh xâm lược tại Việt Nam, qua đó truyền tải thông điệp hòa bình, hòa giải đến du khách trong và ngoài nước Kiến trúc: Tòa nhà nhiều tầng mang phong cách hiện đại với khuôn viên rộng rãi trưng bày các khí tài quân sự hạng nặng ngoài trời', '📍', 'Khám phá', 106.692, 10.7794),
  ('Mũi Cà Mau', 'Lịch sử: Vùng đất Đất Mũi hình thành từ quá trình bồi tụ phù sa tự nhiên qua hàng trăm năm của hệ thống sông rạch Tây Nam Bộ Trong lịch sử mở cõi phương Nam từ thế kỷ 17–18 dưới thời các chúa Nguyễn, nơi đây đánh dấu cột mốc cuối cùng trên đất liền Trong hai cuộc kháng chiến chống Pháp và chống Mỹ, Mũi Cà Mau là căn cứ địa cách mạng kiên cường (Căn cứ Rừng Đước), là nơi tiếp nhận những chuyến tàu Không số thuộc Đường Hồ Chí Minh trên biển tiếp tế vũ khí cho chiến trường miền Nam Ngày nay, Đất Mũi mang giá trị lịch sử - địa lý thiêng liêng về chủ quyền toàn vẹn lãnh thổ của Tổ quốc Kiến trúc: Cảnh quan tự nhiên với hệ sinh thái rừng ngập mặn đặc trưng Khu vực có Cột mốc tọa độ quốc gia GPS 0001 và biểu tượng Con tàu Cà Mau hướng thẳng ra biển Đông', '📍', 'Khám phá', 104.712, 8.623),
  ('Vườn Quốc gia U Minh Hạ', 'Lịch sử: Rừng U Minh có lịch sử hình thành hàng ngàn năm gắn liền với hệ sinh thái than phèn đặc trưng của đồng bằng sông Cửu Long Trong hai cuộc kháng chiến chống xâm lược, U Minh Hạ là "mật khu" cách mạng nổi tiếng, che chở cho các cơ quan đầu não chỉ đạo cách mạng miền Nam và các trung đoàn chủ lực Nhằm bảo tồn tài nguyên thiên nhiên quý giá và giá trị lịch sử chiến khu, Lâm trường U Minh III đã được chuyển đổi thành Vườn Quốc gia U Minh Hạ vào năm 2006 Đến năm 2009, nơi đây chính thức được UNESCO công nhận là 1 trong 3 vùng lõi thuộc Khu Dự trữ sinh quyển thế giới Mũi Cà Mau Kiến trúc: Cảnh quan thiên nhiên hoang sơ với hệ thống sông rạch chằng chịt, rừng tràm bạt ngàn và thảm thực vật đặc trưng vùng đất ngập nước', '📍', 'Khám phá', 104.95, 9.35),
  ('Hòn Đá Bạc', 'Lịch sử: Cụm đảo có niên đại kiến tạo địa chất hơn 180 triệu năm (thuộc kỷ Cổ sinh) Trong thời kỳ chiến tranh chống Mỹ, Hòn Đá Bạc là đồn bốt chiến lược của địch kiểm soát vùng biển phía Tây Cà Mau nhưng đã bị quân dân ta đánh chiếm năm 1971 Đặc biệt, từ năm 1981 đến 1984, nơi đây đã diễn ra Kế hoạch phản gián CM12 lừng lẫy của Lực lượng Công an Nhân dân Việt Nam, đập tan tổ chức phản động do Lê Quốc Túy và Mai Văn Hạnh cầm đầu, thu giữ hàng trăm tấn vũ khí Năm 2009, Bộ Văn hóa, Thể thao và Du lịch đã công nhận Hòn Đá Bạc - Di tích Kế hoạch CM12 là Di tích lịch sử - danh thắng cấp Quốc gia Kiến trúc: Cụm gồm 3 hòn đảo nằm sát nhau (Hòn Trọc, Hòn Đá Bạc và Hòn Đá Lẻ) với các khối đá mảng lớn xếp chồng lên nhau tạo nên cảnh quan kỳ thú', '📍', 'Khám phá', 104.82, 9.1),
  ('Đầm Thị Tường', 'Lịch sử: Là đầm nước tự nhiên hình thành từ quá trình kiến tạo địa chất ven biển hàng ngàn năm trước Tên gọi "Thị Tường" gắn liền với truyền thuyết dân gian khai phá đất phương Nam về bà Tường – một người phụ nữ dũng cảm đã xua đuổi đàn đá thần do Thủy Tề sai đến lấp biển, bảo vệ nguồn sống cho ngư dân Trong kháng chiến chống Pháp và Mỹ, địa hình lòng hồ rộng lớn với hệ thống kênh rạch bao quanh đã biến Đầm Thị Tường thành căn cứ du kích vững chắc, che chở cho nhiều cán bộ cách mạng bám dân hoạt động Kiến trúc: Là đầm nước tự nhiên lớn nhất vùng ĐBSCL dài hơn 12km, mặt nước mênh mông với những nhà sàn rải rác trên sông của người dân làm nghề chài lưới', '📍', 'Khám phá', 104.85, 9.05),
  ('Khu Du lịch Sinh thái Sông Trẹm', 'Lịch sử: Dòng sông Trẹm có lịch sử lâu đời gắn liền với con đường khai hoang mở cõi của lưu dân Nam Bộ vào thế kỷ 18–19 và truyền thuyết tác phẩm văn học nổi tiếng "Bên dòng sông Trẹm" của nhà văn Dương Hà Trong thời kỳ chiến tranh, vùng sông Trẹm là tuyến đường giao thông thủy chiến lược thuộc căn cứ U Minh Đến đầu những năm 2000, Ban Quản lý Rừng đặc dụng U Minh Hạ đã đầu tư xây dựng Khu du lịch sinh thái Sông Trẹm trên diện tích hơn 110ha nhằm bảo tồn đa dạng sinh học hệ sinh thái rừng tràm ngập nước, đồng thời phát triển mô hình du lịch sinh thái gắn liền với lịch sử chiến khu xưa Kiến trúc: Không gian xanh mát ngợp bóng tràm cổ thụ, lối đi cầu tre uốn lượn qua các con kênh và các chòi lá nghỉ chân đậm chất quê Nam Bộ', '📍', 'Khám phá', 104.98, 9.4)
)
INSERT INTO public.checkpoints (name, description, icon, badge, longitude, latitude)
SELECT d.name, d.description, d.icon, d.badge, d.longitude, d.latitude
FROM destinations d
WHERE NOT EXISTS (
  SELECT 1 FROM public.checkpoints c WHERE lower(trim(c.name)) = lower(trim(d.name))
);


-- Fill the new detail columns for seeded destinations after the rows are inserted.
-- Requires supabase/add-destination-details.sql to have been run first.
-- Only labeled information is extracted; missing facts remain NULL instead of being invented.
UPDATE public.checkpoints AS c
SET
  history = COALESCE(
    NULLIF(btrim(c.history), ''),
    NULLIF(btrim((regexp_match(
      COALESCE(c.description, ''),
      '(?is)(?:Lịch sử hình thành|Lịch sử địa chất|Lịch sử)\\s*:\\s*(.*?)(?=\\s*(?:Kiến trúc(?:\\s*/\\s*Cảnh quan|\\s*[–-]\\s*cảnh quan)?|Điểm đặc trưng nhất là|Điểm thú vị|Fun fact|Slogan)\\s*:|$)'
    ))[1]), ''),
    NULLIF(btrim(c.description), '')
  ),
  architecture = COALESCE(
    NULLIF(btrim(c.architecture), ''),
    NULLIF(btrim((regexp_match(
      COALESCE(c.description, ''),
      '(?is)Kiến trúc(?:\\s*/\\s*Cảnh quan|\\s*[–-]\\s*cảnh quan)?\\s*:\\s*(.*?)(?=\\s*(?:Lịch sử hình thành|Lịch sử địa chất|Lịch sử|Điểm đặc trưng nhất là|Điểm thú vị|Fun fact|Slogan)\\s*:|$)'
    ))[1]), '')
  ),
  distinctive_feature = COALESCE(
    NULLIF(btrim(c.distinctive_feature), ''),
    NULLIF(btrim((regexp_match(
      COALESCE(c.description, ''),
      '(?is)(?:Điểm đặc trưng nhất là|Điểm nổi bật)\\s*:\\s*(.*?)(?=\\s*(?:Lịch sử hình thành|Lịch sử địa chất|Lịch sử|Kiến trúc(?:\\s*/\\s*Cảnh quan|\\s*[–-]\\s*cảnh quan)?|Điểm thú vị|Fun fact|Slogan)\\s*:|$)'
    ))[1]), '')
  ),
  fun_fact = COALESCE(
    NULLIF(btrim(c.fun_fact), ''),
    NULLIF(btrim((regexp_match(
      COALESCE(c.description, ''),
      '(?is)(?:Điểm thú vị|Fun fact)\\s*:\\s*(.*?)(?=\\s*(?:Lịch sử hình thành|Lịch sử địa chất|Lịch sử|Kiến trúc(?:\\s*/\\s*Cảnh quan|\\s*[–-]\\s*cảnh quan)?|Điểm đặc trưng nhất là|Slogan)\\s*:|$)'
    ))[1]), '')
  ),
  slogan = COALESCE(
    NULLIF(btrim(c.slogan), ''),
    'Khám phá ' || c.name || ' – lưu giữ dấu ấn Việt Nam.'
  )
WHERE EXISTS (
  SELECT 1 FROM destinations d
  WHERE lower(trim(d.name)) = lower(trim(c.name))
);
